class Solution {
public:
    vector<vector<int>> constructGridLayout(int n, vector<vector<int>>& edges) {
        vector<vector<int>> adj(n);
        vector<unordered_set<int>> aset(n);
        for (auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
            aset[e[0]].insert(e[1]);
            aset[e[1]].insert(e[0]);
        }
        int corner = 0;
        for (int i = 1; i < n; i++)
            if (adj[i].size() < adj[corner].size()) corner = i;
        if (adj[corner].size() == 1) {
            vector<int> row{corner};
            int prev = -1, cur = corner;
            while ((int)row.size() < n) {
                for (int x : adj[cur]) if (x != prev) {
                    row.push_back(x); prev = cur; cur = x; break;
                }
            }
            return {row};
        }
        int d4 = 0;
        for (int i = 0; i < n; i++) if (adj[i].size() == 4) d4++;
        long long s = (n + 4 - d4) / 2;
        long long disc = s * s - 4LL * n;
        long long r = (long long)sqrtl((long double)disc);
        while (r * r < disc) r++;
        while (r * r > disc) r--;
        int cols = 0;
        for (long long c : {(s + r) / 2, (s - r) / 2})
            if (c > 0 && c * (s - c) == n) { cols = (int)c; break; }
        int rows = n / cols;
        int a = adj[corner][0], b = adj[corner][1];
        vector<vector<int>> grid;
        vector<char> used(n, 0);
        grid.push_back({corner, b});
        used[corner] = used[b] = 1;
        while ((int)grid[0].size() < cols) {
            int cur = grid[0].back(), nxt = -1;
            for (int x : adj[cur])
                if (!used[x] && !aset[a].count(x)) { nxt = x; break; }
            grid[0].push_back(nxt);
            used[nxt] = 1;
        }
        for (int i = 1; i < rows; i++) {
            int cur = grid.back()[0], nxt = -1;
            for (int x : adj[cur]) if (!used[x]) { nxt = x; break; }
            vector<int> row{nxt};
            used[nxt] = 1;
            for (int j = 1; j < cols; j++) {
                int above = grid[i - 1][j];
                cur = row.back(); nxt = -1;
                for (int x : adj[cur])
                    if (!used[x] && aset[above].count(x)) { nxt = x; break; }
                row.push_back(nxt);
                used[nxt] = 1;
            }
            grid.push_back(row);
        }
        return grid;
    }
};

