class Solution {
    public int[][] constructGridLayout(int n, int[][] edges) {
        List<List<Integer>> adj = new ArrayList<>();
        List<Set<Integer>> aset = new ArrayList<>();
        for (int i = 0; i < n; i++) { adj.add(new ArrayList<>()); aset.add(new HashSet<>()); }
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]);
            aset.get(e[0]).add(e[1]); aset.get(e[1]).add(e[0]);
        }
        int corner = 0;
        for (int i = 1; i < n; i++)
            if (adj.get(i).size() < adj.get(corner).size()) corner = i;
        if (adj.get(corner).size() == 1) {
            int[] row = new int[n];
            row[0] = corner;
            int prev = -1, cur = corner;
            for (int k = 1; k < n; k++) {
                for (int x : adj.get(cur)) if (x != prev) {
                    row[k] = x; prev = cur; cur = x; break;
                }
            }
            return new int[][]{row};
        }
        int d4 = 0;
        for (int i = 0; i < n; i++) if (adj.get(i).size() == 4) d4++;
        long s = (n + 4 - d4) / 2;
        long disc = s * s - 4L * n;
        long r = (long) Math.sqrt((double) disc);
        while (r * r < disc) r++;
        while (r * r > disc) r--;
        int cols = 0;
        for (long c : new long[]{(s + r) / 2, (s - r) / 2})
            if (c > 0 && c * (s - c) == n) { cols = (int) c; break; }
        int rows = n / cols;
        int a = adj.get(corner).get(0), b = adj.get(corner).get(1);
        int[][] grid = new int[rows][cols];
        boolean[] used = new boolean[n];
        grid[0][0] = corner; grid[0][1] = b;
        used[corner] = used[b] = true;
        for (int j = 2; j < cols; j++) {
            int cur = grid[0][j - 1];
            for (int x : adj.get(cur))
                if (!used[x] && !aset.get(a).contains(x)) { grid[0][j] = x; break; }
            used[grid[0][j]] = true;
        }
        for (int i = 1; i < rows; i++) {
            int cur = grid[i - 1][0];
            for (int x : adj.get(cur)) if (!used[x]) { grid[i][0] = x; break; }
            used[grid[i][0]] = true;
            for (int j = 1; j < cols; j++) {
                int above = grid[i - 1][j];
                cur = grid[i][j - 1];
                for (int x : adj.get(cur))
                    if (!used[x] && aset.get(above).contains(x)) { grid[i][j] = x; break; }
                used[grid[i][j]] = true;
            }
        }
        return grid;
    }
}

