var constructGridLayout = function(n, edges) {
    const adj = Array.from({length: n}, () => []);
    const aset = Array.from({length: n}, () => new Set());
    for (const [u, v] of edges) {
        adj[u].push(v); adj[v].push(u);
        aset[u].add(v); aset[v].add(u);
    }
    let corner = 0;
    for (let i = 1; i < n; i++)
        if (adj[i].length < adj[corner].length) corner = i;
    if (adj[corner].length === 1) {
        const row = [corner];
        let prev = -1, cur = corner;
        while (row.length < n) {
            const nxt = adj[cur].find(x => x !== prev);
            row.push(nxt); prev = cur; cur = nxt;
        }
        return [row];
    }
    let d4 = 0;
    for (let i = 0; i < n; i++) if (adj[i].length === 4) d4++;
    const s = Math.floor((n + 4 - d4) / 2);
    const disc = s * s - 4 * n;
    let r = Math.floor(Math.sqrt(disc));
    while (r * r < disc) r++;
    while (r * r > disc) r--;
    let cols = 0;
    for (const c of [(s + r) / 2, (s - r) / 2])
        if (c > 0 && c * (s - c) === n) { cols = c; break; }
    const rows = n / cols;
    const [a, b] = adj[corner];
    const grid = [];
    const used = new Array(n).fill(false);
    grid.push([corner, b]);
    used[corner] = used[b] = true;
    while (grid[0].length < cols) {
        const cur = grid[0][grid[0].length - 1];
        const nxt = adj[cur].find(x => !used[x] && !aset[a].has(x));
        grid[0].push(nxt);
        used[nxt] = true;
    }
    for (let i = 1; i < rows; i++) {
        const row = [];
        let cur = grid[i - 1][0];
        let nxt = adj[cur].find(x => !used[x]);
        row.push(nxt); used[nxt] = true;
        for (let j = 1; j < cols; j++) {
            const above = grid[i - 1][j];
            cur = row[row.length - 1];
            nxt = adj[cur].find(x => !used[x] && aset[above].has(x));
            row.push(nxt); used[nxt] = true;
        }
        grid.push(row);
    }
    return grid;
};
